/* Linear — dark, dense, engineered calm. Palette derived from awesome-design-md (MIT). */
@theme {
	--color-primary: #5e6ad2;
	--color-primary-foreground: #ffffff;
	--color-surface: #08090a;
	--color-surface-foreground: #f7f8f8;
	--color-surface-raised: #131416;
	--color-muted: #8a8f98;
	--color-accent: #26b5ce;
	--color-danger: #eb5757;
	--color-border: #26282d;

	--radius-sm: 4px;
	--radius-md: 6px;
	--radius-lg: 8px;
	--radius-xl: 12px;
	--radius-2xl: 16px;

	--shadow-sm: 0 1px 2px rgb(0 0 0 / 0.5);
	--shadow-md: 0 4px 16px rgb(0 0 0 / 0.5);
	--shadow-lg: 0 16px 48px rgb(0 0 0 / 0.6);
}

/* Doodle Pop — lime × black sticker energy: thick ink borders, hard offset shadows,
 * polka-dot textures, coral/lavender/sky pastel pops. Original Vetta preset. */
@theme {
	--color-primary: #d6f437;
	--color-primary-foreground: #111111;
	--color-surface: #c8e93c;
	--color-surface-foreground: #111111;
	--color-surface-raised: #ffffff;
	--color-muted: #55584a;
	--color-accent: #f4794f;
	--color-danger: #ef3b5d;
	--color-border: #111111;
	--color-cream: #f2f0e6;
	--color-lavender: #b39df3;
	--color-sky: #8ed8e8;
	--color-ink: #111111;

	--radius-sm: 8px;
	--radius-md: 12px;
	--radius-lg: 16px;
	--radius-xl: 20px;
	--radius-2xl: 28px;

	--shadow-sm: 2px 2px 0 #111111;
	--shadow-md: 4px 4px 0 #111111;
	--shadow-lg: 7px 7px 0 #111111;
}

/* Stripe — polished fintech, blurple on airy blue-gray. Palette derived from awesome-design-md (MIT). */
